class Extractor:
    """Encapsulates the split-repo vs mono-repo differences."""

    def __init__(self, is_split_repo: bool = True):
        self.is_split_repo = is_split_repo
        if is_split_repo:
            self.path_format = SPLIT_REPO_PATH_FORMAT
            self.repos_key = REPO_RESPONSE_KEY
        else:
            self.path_format = MONO_REPO_PATH_FORMAT
            self.repos_key = PACKAGE_RESPONSE_KEY

    def include_repo(self, repo) -> bool:
        return not self.is_split_repo or allowed_repo(repo)

    def client_for_repo(self, repo_slug) -> Optional[CloudClient]:
        path = self.path_format.format(repo_slug=repo_slug)
        url = f"{RAW_CONTENT_BASE_URL}/{path}/{REPO_METADATA_FILENAME}"
        response = requests.get(url)
        if response.status_code != requests.codes.ok:
            return

        return CloudClient(response.json())

    def get_clients_batch_from_response_json(self, response_json) -> List[CloudClient]:
        return [
            self.client_for_repo(repo[self.repos_key])
            for repo in response_json
            if self.include_repo(repo)
        ]


def mono_repo_clients(token: str) -> List[CloudClient]:
    # all mono repo clients
    url = f"{BASE_API}/repos/{MONO_REPO}/contents/packages"
    headers = {'Authorization': f'token {token}'}
    response = requests.get(url=url, headers=headers)

    return Extractor(is_split_repo=False).get_clients_batch_from_response_json(response.json())


def split_repo_clients(token: str) -> List[CloudClient]:
    extractor = Extractor(is_split_repo=True)
    first_request = True
    while first_request or 'next' in response.links:
        if first_request:
            url = f"{BASE_API}/search/repositories?page=1"
            first_request = False
        else:
            url = response.links['next']['url']
        headers = {'Authorization': f'token {token}'}
        params = {'per_page': 100, "q": "python- in:name org:googleapis"}
        response = requests.get(url=url, params=params, headers=headers)
        repositories = response.json().get("items", [])
        if len(repositories) == 0:
            break
        return extractor.get_clients_batch_from_response_json(repositories)
